L000031	\title{Dissipative phase transition of interacting non-reciprocal fermions}
L000032	
L000033	\author{Rafael D. Soares}
L000034	\affiliation{Max Planck Institute for the Physics of Complex Systems, N\"{o}thnitzer Stra{\ss}e 38, 01187 Dresden, Germany}
