L000573	\section{Stability against Disorder and Dephasing}
L000574	\label{sec:disorder_dephasing}
L000575	\begin{figure}[t]
L000576	    \centering
L000577	    \includegraphics{Figs/s5.png}
L000578	    \caption{$a)$ Steady-state current as function of $\phi$ and $\theta$ for a clean system and $b)$ for disorder strength $W=1.0J$ ($L=128$). $c)$ Steady-state density and $d)$ current profiles for a chain of length $L=4096$ at $\phi=\theta=\pi/2$ for different disorder strengths. The inset in $c)$ highlights the reduction of net boundary charge accumulation with increasing disorder and the one in $d)$ shows that the bulk current is independent of the system size. Other parameters: $\Gamma=\kappa=0.1J$.}
