L000602	\section{Linblad Spectrum and Dissipative Gap}\label{sec:lindblad_spectrum}
L000603	
L000604	\begin{figure}[b]
L000605	    \centering
L000606	    \includegraphics{Figs/s7.pdf}
L000607	    \caption{Real component of the Linblad spectra for $\phi=-\theta=\pi/2$ (panel $a)$ and $b)$) and for $\phi=\theta=\pi/2$ (panel $c)$ and $d)$). Panel $a)$ and $c)$ corresponds to the non-interacting limit, $\Delta=0.0J$, while $\Delta=4.0J$ in panel $c)$ and $d)$. Other parameters: $L=8$, $\Gamma=\kappa=0.1J$.}
L000608	    \label{fig:excitation_spectrum_symmetry}
L000609	\end{figure}
L000610	To better characterize the role of interactions, we analyze the spectrum of the Lindbladian superoperator. We use the super-fermion representation~\cite{Dzhioev2011,10.21468/SciPostPhys.9.6.091}, which maps the Lindbladian onto an augmented Hilbert space (the Liouville space), whose dimension with the number of sites $L$ scales as $4^L$. This construction doubles the degrees of freedom by introducing a \textit{tilde} space to encode the action on the bra of the density matrix (see Ref.~\cite{Dzhioev2011} for technical details). In this formalism the Linblad superoperator corresponds to,
L000611	\begin{equation}
L000612	\begin{aligned}
L000613	\mathcal{L}	&=\sum_{j}\left[J_{R}c_{j}^{\dagger}c_{j+1}+J_{L}c_{j+1}^{\dagger}c_{j}+J_{R}^{\ast}f_{j}^{\dagger}f_{j+1}+J_{L}^{\ast}f_{j+1}^{\dagger}f_{j}-\Delta\left(n_{j}n_{j+1}-\tilde{n}_{j}\tilde{n}_{j+1}\right)\right] \\
L000614	&+\left(\Gamma-\kappa\right)\sum_{j}\left[c_{j}^{\dagger}c_{j}+f_{j}^{\dagger}f_{j}\right]+i\kappa\sum_{j}\left[2f_{j}c_{j}+e^{i\phi}f_{j}c_{j+1}+e^{-i\phi}f_{j+1}c_{j}\right] \\
L000615	&+i\Gamma\sum_{j}\left[\left(2f_{j}^{\dagger}c_{j}^{\dagger}+e^{i\theta}f_{j}^{\dagger}c_{j+1}^{\dagger}+e^{-i\theta}f_{j+1}^{\dagger}c_{j}^{\dagger}\right)\right]-2L\Gamma.
L000616	\end{aligned}
L000617	\end{equation}
L000618	where $f_j(f^\dagger_j)$ are fermion creation(annihilation) operators that act on the \textit{tilde} Fock space that satisfy the standard fermionic anticommutation relations, $J_{R}=\frac{i}{2}J+\frac{1}{2}\kappa e^{i\phi}-\frac{1}{2}\Gamma e^{-i\theta}$ and $J_{L}=\frac{i}{2}J+\frac{1}{2}\kappa e^{-i\phi}-\frac{1}{2}\Gamma e^{i\theta}$.
L000619	
L000620	We obtain the symmetry-resolved spectra of the Linblad by employing translational symmetries (when considering PBC) and the $U(1)$ symmetry generated by $\mathcal{S}=\sum_j \left( c^\dagger_jc_j - f^\dagger_jf_j \right)$ as $\left[\mathcal{L}, \mathcal{S} \right]=0$. The latter is a consequence of the weak $U(1)$ symmetry related to the particle number operator. We note that all Hermitian eigenmatrices of the Lindblad superoperator (which have real eigenvalues) belong to the \( \mathcal{S}=0 \) sector.
L000621	
L000622	In the non-interacting limit, the vectorized Lindblad superoperator admits an exact analytic diagonalization, yielding the same single-particle spectrum as obtained from the retarded Keldysh Green’s function in section~\ref{sec:keldysh_section},
L000623	\begin{equation}
L000624	    \mathcal{L} = \left( -i \varepsilon_k - \frac{1}{2}\lambda_k \right) D^\dagger_k d_k +\left( i \varepsilon_k - \frac{1}{2}\lambda_k \right) \tilde{d}^\dagger_{-k} \tilde{D}_{-k},
L000625	    \label{eq:free_linblad}
L000626	\end{equation}
L000627	where $d_k, D_k^\dagger$ and $\tilde d_k, \tilde D_k^\dagger$ denote fermionic modes acting on the original and \textit{tilde} Fock spaces, respectively. Within this formalism, the steady state is defined as the state annihilated by all \( d_k \) and \( \tilde D_k \), while the decaying modes are generated by the action of \( D_k^\dagger \) and \( \tilde d_k^\dagger \) upon it.
L000628	
L000629	\begin{figure}[t]
L000630	    \centering
L000631	    \includegraphics{Figs/s8.pdf}
L000632	    \caption{Real part of the spectrum as a function of $\Delta/J$ for $\phi=-\theta=\pi/2$ $a)$ and $\phi=\theta=\pi/2$ $b)$. Other parameters: $L=12$ and $\Gamma=\kappa=0.1J$.}
L000633	    \label{fig:symmetry_resolved_spectrum_interactions}
L000634	\end{figure}
L000635	We now discuss the structure of the real part of the Linblad spectra, which is responsible for the decaying of the modes. In Fig.~\ref{fig:excitation_spectrum_symmetry}, we plot the symmetry resolved real-part of the spectrum for different parameters. In the non-interacting limit defined by $\phi=-\theta$ (Fig.~\ref{fig:excitation_spectrum_symmetry}(a)), we observe four eigenvalues with zero real parts. Two of these correspond to Hermitian density matrices with zero momentum. These states represent the degenerate steady states:
L000636	\begin{equation}
L000637	    \rho^{(1)}_{\mathrm{ss}} = \dfrac{\mathbb{I}_{2^N\times 2^N}}{2^N}, \quad \rho^{(2)}_{\mathrm{ss}} = \dfrac{c^\dagger_{k^\ast}c_{k^\ast}}{2^{N-1}}.
L000638	\end{equation}
L000639	The remaining two states lie in the $\mathcal{S}=\pm1$ sectors with momenta $k^\ast$ and $-k^\ast$, respectively, corresponding to the non-normalized density matrices
L000640	\begin{equation}
L000641	    \rho_{\mathcal{S}=1,k=k^\ast} = c^\dagger_{k^\ast},\quad \rho_{\mathcal{S}=-1,k=-k^\ast} = c_{k^\ast}.
L000642	\end{equation}
L000643	This is a natural consequence of the dark mode of the Linblad as modes with momentum $k^\ast$ are transparent to the dissipation. In contrast, whenever $\phi\neq-\theta$, all modes acquire finite dissipation, as illustrated in Fig.~\ref{fig:excitation_spectrum_symmetry}(c) for the case $\phi=\theta=\pi/2$. Specifically, for these angles and with $\Gamma=\kappa$, the dissipative component becomes momentum-independent, given by $\lambda_k=4\Gamma$. This is reflected in a constant spacing of $2\Gamma$ observed between the different eigenvalues. In this regime, the steady state resides in the zero-momentum sector, while the second longest-lived modes belong to the $\mathcal{S}=\pm1$ sectors, corresponding to the operators:
L000644	\begin{equation}
L000645	    \rho_{\mathcal{S}=1,k} = c^\dagger_{k} \rho_{\mathrm{ss}}, \quad \rho_{\mathcal{S}=-1,k} = \rho_{\mathrm{ss}}c_{k}.
L000646	\end{equation}
L000647	We also observe that in this non-interacting limit, most eigenvalues are degenerate with respect to the real part. The degree of degeneracy naturally depends on the system parameters and can be predicted from Eq.~\eqref{eq:free_linblad}. On the other hand, in the presence of interactions, most of these degeneracies are lifted\footnote{ The remaining ones stem from the trace-preserving and Hermiticity-preserving nature of the Lindblad superoperator.} and there is the opening of the many-body dissipative gap for $\phi=-\theta=\pi/2$ Fig.~\ref{fig:excitation_spectrum_symmetry}(b) or its enhancement for $\phi=\theta=\pi/2$ as shown in Fig.~\ref{fig:excitation_spectrum_symmetry}(c).
L000648	
L000649	To better characterize the dissipative gap with the interaction strength, in Fig.~\ref{fig:symmetry_resolved_spectrum_interactions}, we show the dependence of the symmetry-resolved decay spectra on the interaction strength for $\phi=-\theta=\pi/2$ (Fig.~\ref{fig:symmetry_resolved_spectrum_interactions} (a) and $\phi=\theta=\pi/2$ (Fig.~\ref{fig:symmetry_resolved_spectrum_interactions} (b). Owing to translational symmetry, the steady state remains in the zero-momentum sector with $\mathcal{S}=0$, which for the critical line $\phi=-\theta$, it is insensitive to the interaction term, $\Delta$, and it always corresponds to the infinite-temperature steady state just like in the non-interacting limit (check section~\ref{sec:steady_state_critical_line} for the proof),
L000650	\begin{equation}
L000651	\rho_{\rm ss,\phi=-\theta} = \bigotimes_{j=1}^{L} \left( \dfrac{\kappa}{\Gamma+\kappa}\left|0 \right\rangle \left\langle 0 \right| + \dfrac{\Gamma}{\Gamma+\kappa}\left|1 \right\rangle \left\langle 1 \right| \right),
L000652	\label{eq:steady_state_density_matrix}
L000653	\end{equation}
L000654	with a net particle density fixed by the pump and loss rates, $\langle n_j\rangle_{\rm ss} = \Gamma/(\Gamma+\kappa)$. From Fig.~\ref{fig:symmetry_resolved_spectrum_interactions} (a), we observe that the dissipative gap increases monotonically with increasing $\Delta$. In the weak-interaction regime $\Delta \ll J$, the slowest relaxation rate is determined by a mode in the $\mathcal{S}=\pm1$ sector and $k=\mp k^\ast$. By contrast, for $\Delta \sim J$ and larger, the slowest mode lies in the zero-momentum sector with $\mathcal{S}=0$ and can be continuously connected, in the non-interacting limit, to the degenerate steady state. Given the possible system sizes accessible within our computational resources, results obtained in the limit $\Delta \to 0$ require careful interpretation regarding finite-size corrections. A critical factor is the closure of the dissipative gap at a specific finite momentum. Consequently, if this momentum is incommensurate with the discrete momentum grid defined by the chain length, $k=2\pi \, n/L$, with $n\in\mathbb{Z}_L$, the true minimum of the dissipative spectrum may remain unresolved.
L000655	
L000656	
L000657	At $\phi=\theta=\pi/2$, the system exhibits a gap even in the non-interacting limit. However, interactions further enhance this dissipative gap. With increasing $\Delta$, the quantum numbers of the gap change. Initially determined by a finite-momentum state in the $\mathcal{S}=\pm 1$ sector, the gap becomes dictated by a zero-momentum state in the $\mathcal{S}=0$ sector for $\Delta > J$. Notably, the decay rate associated with this zero-momentum state is insensitive to interaction strength. This robustness arises because, at $\Gamma=\kappa$, the state corresponds to the infinite-temperature density matrix, which is insensitive to the Hamiltonian term.
L000658	
L000659	\section{Steady-state density-matrix along the critical line $\phi=-\theta$}
L000660	\label{sec:steady_state_critical_line}
L000661	In this appendix, we prove that the density matrix given in Eq.~\eqref{eq:steady_state_density_matrix} corresponds to the steady-state density matrix along the line $\phi=-\theta$, independent of $\Delta$ and the boundary conditions.
L000662	
L000663	First, we observe that Eq.~\eqref{eq:steady_state_density_matrix} can be explicitly written as a Gaussian density matrix,
L000664	\begin{equation}
L000665	    \rho_{\text{ss},\phi=-\theta} = \frac{1}{\mathcal{Z}} \exp\left(\ln\left(\dfrac{\Gamma}{\kappa}\right) N \right),
L000666	\end{equation}
L000667	where $\mathcal{Z}=\left(\kappa/(\Gamma+\kappa) \right)^L$ is the normalization factor and $N=\sum_{j} n_j$ is the total particle number operator. As the Hamiltonian conserves the total particle number (i.e., $\left[\mathcal{H},N \right]=0$) even in the presence of interactions (or the disorder potential considered in Sec.~\ref{sec:disorder_dephasing}) and for any boundary conditions, and because $\rho_{\text{ss}}$ is strictly a function of $N$, it follows that this density matrix does not evolve under the coherent part of the evolution:
L000668	\begin{equation}
L000669	    \left[\mathcal{H},\rho_{\text{ss},\phi=-\theta}\right] = 0.
L000670	\end{equation}
L000671	
L000672	To prove that the density matrix is invariant under the dissipative part of the Lindblad master equation, it is useful to write the density matrix in the product state form:
L000673	\begin{equation}
L000674	    \rho_{\text{ss},\phi=-\theta} = \frac{1}{\mathcal{Z}}\bigotimes_{j=1}^L \tilde{\rho}_j,
L000675	    \label{eq:decompositon_inf_temp}
L000676	\end{equation}
L000677	with $\tilde{\rho}_j=\left(1+(\Gamma/\kappa-1)n_j \right)$. This exponential form yields the following useful commutation relation for any annihilation operator $c_m$:
L000678	\begin{equation} \label{eq:commutation_relation}
L000679	    c_{m}\;\rho_{\text{ss},\phi=-\theta} = \left(\frac{\Gamma}{\kappa}\right)\rho_{\text{ss},\phi=-\theta}\; c_{m}.
L000680	\end{equation}
L000681	The dissipative part that acts on $\rho_{\text{ss},\phi=-\theta}$ due to both gain and loss processes is given by
L000682	\begin{equation}
L000683	    \mathcal{D}[\rho_{\text{ss},\phi=-\theta}]=\sum_j\left( L_{j,\ell}\; \rho_{\text{ss},\phi=-\theta} \;L^\dagger_{j,\ell} + L_{jg} \;\rho_{\text{ss},\phi=-\theta}\; L^\dagger_{j,g}  -\frac{1}{2}\left\{L^\dagger_{j,\ell}L_{j,\ell}, \rho_{\text{ss},\phi=-\theta}   \right\} -\frac{1}{2}\left\{L^\dagger_{j,g}L_{j,g}, \rho_{\text{ss},\phi=-\theta}  \right\} \right).
L000684	\end{equation}
L000685	We note that $\left[\sum_j L^\dagger_{j,\mu} L_{j,\mu}, N \right]=0$ for $\mu \in \{\ell, g\}$. Consequently $\left[\sum_j L^\dagger_{j,\mu} L_{j,\mu}, \rho_{\text{ss},\phi=-\theta} \right]=0$, and so the anti-commutator terms simplify to a standard product. Using this last property and the commutation relation in Eq.~\eqref{eq:commutation_relation}, we can rewrite the dissipator as:
L000686	\begin{equation}
L000687	\begin{aligned}
L000688	\mathcal{D}[\rho_{\text{ss},\phi=-\theta}] &=\sum_j\left( \left[ \frac{\Gamma}{\kappa}L_{j,\ell} L^\dagger_{j,\ell} -L^\dagger_{j,g} L_{j,g} \right] \rho_{\text{ss},\phi=-\theta} + L_{j,g}\; \rho_{\text{ss},\phi=-\theta} \;L^\dagger_{j,g}  - \frac{\Gamma}{\kappa} L^\dagger_{j,g}\; \rho_{\text{ss},\phi=-\theta}\; L_{j,g}\right).
L000689	\end{aligned}
L000690	\end{equation}
L000691	Replacing the jump operators with their explicit expressions, we obtain:
L000692	\begin{equation}
L000693	\begin{aligned}
L000694	\mathcal{D}[\rho_{\text{ss},\phi=-\theta}] &= \Gamma\left( \left[e^{i\phi}-e^{-i\theta}\right]c_{j+1}c_{j}^{\dagger} + \left[e^{-i\phi}-e^{i\theta}\right]c_{j}c_{j+1}^{\dagger} \right)\rho_{\text{ss},\phi=-\theta} \\
L000695	&\quad + \left(e^{i\theta}-e^{-i\phi}\right)c_{j+1}^{\dagger}\rho_{\text{ss},\phi=-\theta} c_{j} + \left(e^{-i\theta}-e^{i\phi}\right)c_{j}^{\dagger}\rho_{\text{ss},\phi=-\theta} c_{j+1}.
L000696	\end{aligned}
L000697	\end{equation}
L000698	Finally, we observe that if $\phi=-\theta$, the prefactors in parentheses vanish. Thus, we conclude that:
L000699	\begin{equation}
L000700	    \phi=-\theta \implies \mathcal{D}[\rho_{\text{ss},\phi=-\theta}]=0.
L000701	\end{equation}
L000702	Given the decomposition in Eq.~\eqref{eq:decompositon_inf_temp}, it follows that all off-diagonal two-point correlators vanish. The only non-zero contribution arises from the diagonal terms corresponding to the local particle density:
L000703	\begin{equation}
L000704	    \langle c^\dagger_m c_n \rangle = \delta_{mn} \frac{\Gamma}{\Gamma+\kappa}.
L000705	\end{equation}
L000706	This result implies a vanishing particle current for every $\Delta$, which corroborates the numerical results presented in the main text.
L000707	
L000708	
L000709	\section{Lindbladian in the Rotating Frame and Doublon only Dynamics}
L000710	
L000711	Here we briefly discuss the dynamics in the regime $\Delta\gg J$. To this extent it is convenient to perform a unitary transformation and move into a rotating frame, i.e., define a new density matrix $\Tilde{\rho}=V\rho V^{\dagger}$ with $V$ unitary operator of the form
L000712	\begin{align}
L000713	V=\exp(-iKt),
L000714	\end{align}
L000715	and $K$ a suitable operator. In this frame the Lindblad equation for the density matrix  $\Tilde{\rho}$ reads
L000716	\begin{equation}\label{eqn:lindblad2}
L000717	\partial_{t}\Tilde{\rho}=-i\left[\Tilde{\mathcal{H}},\Tilde{\rho}\right]+\sum_{j\mu}\Tilde{L}_{j\mu}\Tilde{\rho} \Tilde{L}_{j\mu}^{\dagger}-\dfrac{1}{2}\left\{ \Tilde{L}_{j\mu}^{\dagger}\Tilde{L}_{j\mu},\Tilde{\rho}\right\},
L000718	\end{equation}
L000719	where we have defined respectively the rotated Hamiltonian $\Tilde{\mathcal{H}}$
L000720	\begin{align}
L000721	\Tilde{\mathcal{H}}=i\left(\partial_t V\right)V^{\dagger}+V HV^{\dagger},
L000722	\end{align}
L000723	and the rotated jump operators
L000724	\begin{align}
L000725	\Tilde{L}_{j\mu}=V L_{j\mu}V^{\dagger},\,\qquad\,
L000726	\Tilde{L}^{\dagger}_{j\mu}=V L^{\dagger}_{j\mu}V^{\dagger}.
L000727	\end{align}
L000728	We choose the unitary as
L000729	\begin{align}
L000730	V=\exp(-i\Delta D t),
L000731	\end{align}
L000732	where $D=\sum_{i} n_in_{i+1}$ is the total number of next-neighbor doublons. This is picked, so that, the rotated Hamiltonian does not contain anymore the interaction term~\cite{seetharam2018absence,peronaci2018resonant}, namely
L000733	\begin{equation}
L000734	\Tilde{\mathcal{H}}=i\left(\partial_t V\right)V^{\dagger}+V \mathcal{H}V^{\dagger}=V \mathcal{H}_0V^{\dagger}
L000735	\end{equation}
L000736	with $\mathcal{H}_0=-\frac{J}{2}\sum_{j=0}^{L-2}\left[c_{j}^{\dagger}c_{j+1}+c_{j+1}^{\dagger}c_{j}\right]$. The price to pay is the rotation of single particle operators in the frame generated by $V$. After simple manipulation these take the form
L000737	\begin{align}
L000738	Vc_jV^{\dagger}&= c_j\,e^{i\Delta (n_{j-1}+n_{j+1})t}.
L000739	\end{align}
L000740	We see from this expression that the dressed destruction operator now gains a phase factor that depends on the occupation of neighboring sites. In particular, starting from an occupied site $i$ we see that if either $j-1$ or $j+1$ are occupied, that is, in the presence of a doublon, the destruction operator gets a phase that rapidly oscillates at large $\Delta$ and thus averages out. Similarly for the creation operator we get
L000741	\begin{equation}
L000742	Vc^{\dagger}_jV^{\dagger}=c^{\dagger}_j\,e^{-i\Delta (n_{j-1}+n_{j+1})t}.
L000743	\end{equation}
L000744	As a consequence the hopping term entering the renormalized Hamiltonian reads
L000745	\begin{align}
L000746	\Tilde{\mathcal{H}}&= V\mathcal{H}_0V^{\dagger} = \sum_j e^{-i\Delta t(n_{j-1}-n_{j+2})}c^{\dagger}_jc_{j+1}+\text{h.c.},
L000747	\end{align}
L000748	For what concerns the dissipative processes, we see that the dressed loss term corresponds to
L000749	\begin{align}
L000750	\Tilde{L}_{j,\ell}=\sqrt{\kappa}(e^{i\Delta (n_{j-1}+n_{j+1})t} c_j+ e^{i\phi}e^{i\Delta t(n_{j}+n_{j+2})t} c_{j+1}),
L000751	\end{align}
L000752	while the gain reads
L000753	\begin{align}
L000754	\Tilde{L}_{j,g}=\sqrt{\Gamma}(e^{-i\Delta (n_{j-1}+n_{j+1})t} c^{\dagger}_j+ e^{i\theta}e^{-i\Delta t(n_{j}+n_{j+2})t} c^{\dagger}_{j+1}).
L000755	\end{align}
L000756	In the rotated frame, the dynamics is described by a correlated hopping process with correlated gain and losses. In particular, coherent evolution contains resonant hopping processes between sites $j,j+1$ that conserve the doublon number (if $n_{j-1}=n_{j+2}$) and off-resonant ones, for $n_{j-1}\neq n_{j+2}$, which rapidly oscillate at frequency $\Delta$ and average out for $\Delta\gg J$ leading to doublon-only dynamics. In this regime, both gain and loss processes are also kinetically blocked, as they can only connect states that differ in doublon number and thus dissipate with a rapidly oscillating phase. As a result, for $\Delta \gg J$, the dynamics become increasingly coherent, and charge accumulation at the boundary is suppressed, as we observe numerically.
L000757	
L000758	
